const e={model:"gemma4:12b",digest:"4eb23ef187e2c5462566d6a1d3bbbc2f1346d0b4327cbb66d58fffbcc9b2b05c",promptVersion:3,date:"2026-08-30",status:{"se.character.awareness.why":"reviewed","se.character.control.why":"reviewed","se.character.endurance.why":"reviewed","se.character.precision.why":"reviewed","se.character.speed.why":"reviewed","se.energy.recovery.auxiliary":"reviewed","se.energy.recovery.dominant":"reviewed","se.energy.recovery.inferior":"reviewed","se.energy.recovery.shadow":"reviewed","se.energy.recovery.tertiary":"reviewed","se.feeder.fe":"reviewed","se.feeder.fi":"reviewed","se.feeder.ni":"reviewed","se.feeder.te":"reviewed","se.feeder.ti":"reviewed","se.fieldNotes.mirror":"reviewed","se.fieldNotes.vignette.court":"reviewed","se.fieldNotes.vignette.fiveYearPlan":"reviewed","se.fieldNotes.vignette.grip":"reviewed","se.fieldNotes.vignette.loop":"reviewed","se.fieldNotes.vignette.mistakenForNe":"reviewed","se.fieldNotes.vignette.reckless":"reviewed","se.fieldNotes.vignette.scheduledBody":"reviewed","se.hero.heading":"reviewed","se.hero.subtitle":"reviewed","se.hero.tag":"reviewed","se.lab.btn.blackout.label":"reviewed","se.lab.btn.blackout.sub":"reviewed","se.lab.btn.flicker.label":"reviewed","se.lab.btn.flicker.sub":"reviewed","se.lab.btn.window.label":"reviewed","se.lab.btn.window.sub":"reviewed","se.lab.intensity.aria":"reviewed","se.lab.intensity.heading":"reviewed","se.lab.intensity.max":"reviewed","se.lab.intensity.min":"reviewed","se.lab.meter.pleasure":"reviewed","se.lab.meter.stress":"reviewed","se.lab.narration.blackout":"reviewed","se.lab.narration.blackout2":"reviewed","se.lab.narration.flicker":"reviewed","se.lab.narration.flicker2":"reviewed","se.lab.narration.flickerMiss":"reviewed","se.lab.narration.hoverCoarse":"reviewed","se.lab.narration.hoverFine":"reviewed","se.lab.narration.intro":"reviewed","se.lab.narration.introHintCoarse":"reviewed","se.lab.narration.introHintFine":"reviewed","se.lab.narration.slider":"reviewed","se.lab.narration.window":"reviewed","se.lab.narration.windowHit":"reviewed","se.lab.narration.windowMiss":"reviewed","se.lab.state.blackout":"reviewed","se.lab.state.equilibrium":"reviewed","se.lab.state.flow":"reviewed","se.lab.state.hunger":"reviewed","se.lab.state.late":"reviewed","se.lab.telemetry.clarity":"reviewed","se.lab.telemetry.cogState":"reviewed","se.lab.telemetry.crossHead":"reviewed","se.lab.telemetry.lock":"reviewed","se.lab.telemetry.sibPleasure":"reviewed","se.lab.telemetry.sibStress":"reviewed","se.lab.telemetry.visitSi":"reviewed","se.meta.title":"reviewed","se.slot.auxiliary":"reviewed","se.slot.critical":"reviewed","se.slot.demon":"reviewed","se.slot.dominant":"reviewed","se.slot.inferior":"reviewed","se.slot.opposing":"reviewed","se.slot.tertiary":"reviewed","se.slot.trickster":"reviewed","se.zoneA.canvasAria":"reviewed","se.zoneB.ageNote":"reviewed","se.zoneB.heading":"reviewed","se.zoneB.lede":"reviewed","se.zoneB.railAria":"reviewed","se.zoneC.heading":"reviewed","se.zoneC.lede":"reviewed","se.zoneC.unstableDefault":"reviewed","se.zoneD.canvasAria":"reviewed","se.zoneD.heading":"reviewed","se.zoneD.kicker":"reviewed","se.zoneD.lede":"reviewed","se.zoneE.lede":"reviewed"}},n={_meta:e,"se.character.awareness.why":"le contact précède l'autorapport : il agit, puis découvre qu'il a agi","se.character.control.why":"suit plus facilement l'action du champ qu'un programme interne","se.character.endurance.why":"le contact avec le sol à l'instant présent — un terrain réel peut être parcouru pendant des heures","se.character.precision.why":"résolution complète sans aucun délai, pendant toute la durée du contact","se.character.speed.why":`se.character.speed.why
verrouillé dans une seule image — l'événement le plus rapide de la psyché`,"se.energy.recovery.auxiliary":"Rapidement, une fois que les outils sont rangés et que la scène est terminée.","se.energy.recovery.dominant":"Se recharge pendant l'utilisation — un contact complet coûte moins cher qu'un repos médiocre.","se.energy.recovery.inferior":"Le plateau de la gueule de bois : ~30 min où la surstimulation persiste et où chaque canal faiblit.","se.energy.recovery.shadow":"Incomplet — la tension dépensée ici ne revient pas entièrement aujourd'hui.","se.energy.recovery.tertiary":"Le plan doit être mis de côté en premier ; une présence acquise selon un calendrier se rétablit sur un autre.","se.feeder.fe":{figure:"Le temps de présence s'effondre à zéro ; le réticule poursuit les applaudissements.",mechanism:"La boucle ESTP, avec Ti retiré : Fe — feeling extraverti — fournit des cibles, mais seulement sociales — le rire, la réaction, le prochain défi de la salle — et chaque succès est dépensé immédiatement pour préparer le suivant. Rien n'est examiné, rien n'est savouré ; le spectacle s'intensifie simplement. La pièce manquante est la question calme de la fonction auxiliaire : est-ce vraiment une bonne idée ?",pair:"la boucle Se–Fe de l'ESTP",provenance:"community",warn:"Couplage en boucle : dominante et tertiaire, toutes deux extraverties — le contrôle interne de la auxiliaire est coupé."},"se.feeder.fi":{figure:"Les cibles de droite brillent et le réticule persiste.",mechanism:"Fi — sentiment introverti — remet à l'œil un critère ressenti : ce qui est beau, ce qui est honnête, ce qui vaut la peine d'être savouré. Le monde se trie par importance, et un verrou est conservé bien après son utilité tactique, car le point n'a jamais été la tactique. Le regard du performeur et de l'esthète : présence totale, tournée vers ce que le cœur a déjà choisi.",pair:"Le couplage ISFP · ESFP",provenance:"myers"},"se.feeder.ni":{figure:"Les verrous s'interrompent à mi-chemin, encore et encore.",mechanism:"Ni — intuition introvertie — interrompt constamment la recherche de sens : chaque verrou s'interrompt à mi-chemin car la cible est déjà devenue un symbole de autre chose. L'œil se repositionne constamment et ne finit rien ; le monde est entièrement présent et jamais réellement vu. Ces deux partagent un axe pour une raison — les piles réelles placent un juge entre eux.",pair:"La perception alimente la perception",provenance:"myers",warn:"Couplage instable : une perception alimentatrice d'une autre, sans jugement de part et d'autre."},"se.feeder.te":{figure:"Le réticule parcourt une liste de contrôle qui se réapprovisionne d'elle-même.",mechanism:"La boucle ESFP, avec Fi écartée : Te — pensée extravertie — transforme le champ en une liste de tâches — visible, finissable, immédiatement remplacée — et l'œil passe d'une course à l'autre à pleine vitesse. Le mouvement devient sa propre preuve de progrès ; si tout cela importe à la personne qui le fait est précisément la question que la boucle ignore.",pair:"la boucle Se–Te de l'ESFP",provenance:"community",warn:"Couplage en boucle : dominante et tertiaire, toutes deux extraverties — le contrôle interne de la auxiliaire est coupé."},"se.feeder.ti":{figure:"Des étiquettes de mesure fleurissent sur tout ce que le réticule verrouille.",mechanism:"Ti — pensée introvertie — donne à l'œil une spécification : tolérances, mécanismes, la mesure unique qui règle la question. La saillance se réorganise autour de ce qui importe — moins de cibles, verrouillées plus fermement, lues au millimètre. Le regard du dépannage : la machine devant vous, interrogée partie par partie, et le diagnostic vérifié par rapport à la chose elle-même.",pair:"Le couplage ISTP · ESTP",provenance:"myers"},"se.fieldNotes.mirror":{figure:"L'une est l'eau qui regarde ; l'autre est l'eau qui garde.",mechanismHtml:"Même élément, attitude opposée — et la différence est ce qui arrive au moment. <strong>Se</strong> le chevauche : résolution complète, zéro décalage, rien conservé — le monde comme un lieu d'action. <strong>Si</strong> le stocke : apport mesuré, comparé à chaque couche qu'il a jamais déposée — le monde comme un lieu de reconnaissance. Se troque le registre pour le moment ; Si troque le moment pour un registre qu'aucun moment ne peut enlever.",provenance:"jung"},"se.fieldNotes.vignette.court":{figure:"Visée, verrouillage, lancement — un seul cadre.",kind:"type d'observation",mechanism:"En milieu de partie, un ESTP voit le transfert de poids du défenseur une demi-seconde avant que la voie ne s'ouvre, et est déjà en mouvement. Demande comment ils le savaient, ils disent qu'ils l'ont vu — ce qui est toute la réponse. Il n'y avait aucune inférence à rapporter ; la perception et le mouvement étaient un seul événement, et l'entretien à ce sujet est la première partie qui a un coût.",provenance:"community",title:"Le terrain de jeu"},"se.fieldNotes.vignette.fiveYearPlan":{figure:"L'instrument le plus tranchant du bâtiment, sans aucune emprise.",kind:"l'instrument erroné",mechanism:"Confiez à Se la stratégie hors site — le marché en 2031, la question de la succession, le pari dont personne dans la pièce ne verra le résultat cette année — et le contact n'a aucune prise, car l'avenir n'en a pas encore. Un profil Se dominant affirmé ne simule pas la vision à long terme ; il s'associe à quelqu'un qui la possède et prend en charge la partie du plan qui s'ancre dans le réel ce trimestre — ce qui, exécuté à sa résolution propre, est un apport qu'aucun planificateur ne peut égaler.",provenance:"community",title:"Le plan sur cinq ans"},"se.fieldNotes.vignette.grip":{figure:"L'iris cède à un entonnoir sombre.",kind:"l'emprise",mechanism:"Un ESFP ayant épuisé ses réserves cesse de percevoir et commence à pressentir — des certitudes sombres soudaines sur ce que tout cela signifie et vers quoi cela se dirige, délivrées sans aucun des habiletés de l'intuition dominante. Pas un changement de personnalité : un siège à faible capacité recevant un flux de taille dominante.",provenance:"quenk",title:"L'emprise"},"se.fieldNotes.vignette.loop":{figure:"Chaque tour de force en achète le suivant ; la porte ne se ferme jamais.",kind:"la boucle",mechanism:"Un ESTP sous pression couple Se dominante avec Fe tertiaire : la réaction de la salle devient l'unique instrument, et chaque exploit en achète le suivant. La question silencieuse de Ti — est-ce vraiment une bonne idée ? — est la fonction que la boucle cherche à éviter. De l'intérieur, cela ressemble à être sur scène ; de l'extérieur, cela ressemble à une escalade.",provenance:"community",title:"La boucle"},"se.fieldNotes.vignette.mistakenForNe":{figure:"Cette vague, et non une meilleure idée d'une autre.",kind:"la lecture erronée",mechanism:"Toutes deux sont lues comme « spontanées », et les deux sont confondues dans les deux sens. L'indice est l'objet de l'appétit. Se veut la chose réelle à intensité réelle — cette vague, cette foule, ce moteur — et trouve que parler de vagues hypothétiques est un mauvais substitut pour l'eau. Ne veut la possibilité et troquera le concert devant elle pour une meilleure idée de concert. Regardez où l'attention se pose quand les deux sont dans une même pièce : l'une sur la scène, l'autre sur ce que le lieu pourrait devenir.",provenance:"community",title:"Confondu avec Ne"},"se.fieldNotes.vignette.reckless":{figure:"Données de fréquence d'images que la barrière de sécurité ne voit jamais.",kind:"l'accusation",mechanism:"Le verdict est généralement rendu par quelqu'un dont l'estimation du risque reposait sur le précédent plutôt que sur la scène. Ce que l'accusateur ne peut pas voir est la résolution : le cavalier a lu cette surface, cette inclinaison, cette emprise, au taux de rafraîchissement, et a évalué le mouvement par rapport à des données qu'il n'aura jamais depuis la barrière de sécurité. Le taux d'erreur de la Se dominante est souvent le plus bas là où les enjeux sont les plus élevés — c'est ce que le contact total permet d'acheter. La mise en garde honnête se situe plus bas dans la pile : le même mouvement depuis le siège tertiaire ou inférieur fonctionne sur une fraction de la résolution et avec tout l'appétit.",provenance:"community",title:"Téméraire"},"se.fieldNotes.vignette.scheduledBody":{figure:"Ouverture complète, sur rendez-vous.",kind:"en tant que tertiaire",mechanism:"Se tertiaire chez un ENTJ ou ENFJ : présence, achetée par blocs. Le week-end moto, le cours de boxe à dix-huit, la cuisine rénovée aux normes restaurant — contact réel avec le monde physique, véritablement apprécié, et inscrit au calendrier par la machinerie à long terme qui gère le reste de la semaine. L'indice est la transition : pleinement dans le corps le samedi, et dès lundi, les sens sont revenus au résumé exécutif.",provenance:"grant",title:"Le Corps Planifié"},"se.hero.heading":"L'œil nu de {fn}","se.hero.subtitle":"Une pupille grande ouverte en contact direct avec le champ en direct — le monde à travers elle plus net, plus rapide et plus saturé que le monde à côté. Rien entre. Rien retenu.","se.hero.tag":"sensation extravertie","se.lab.btn.blackout.label":"Extinction des feux","se.lab.btn.blackout.sub":"le champ se vide — rien à percevoir","se.lab.btn.flicker.label":"Un éclat dans la foule","se.lab.btn.flicker.sub":"un élément change pendant 300 ms","se.lab.btn.window.label":"Fermer la fenêtre","se.lab.btn.window.sub":"une ouverture apparaît — et commence à se fermer","se.lab.intensity.aria":"Intensité du champ de stimulation, d'une pièce vide à un carnaval de rue","se.lab.intensity.heading":"Intensité du champ","se.lab.intensity.max":"carnaval de rue","se.lab.intensity.min":"pièce vide","se.lab.meter.pleasure":"Contacter le Plaisir","se.lab.meter.stress":"Stress","se.lab.narration.blackout":{figure:"La dernière chose vue s'éteint comme une image rémanente ; le petit éclat qui s'en détache, étiqueté pour Si, est la strate que son homologue aurait conservée.",mechanism:"Le champ disparaît, et l'œil commence à payer pour le silence — le stress grimpe dans une pièce vide comme d'autres fonctions paient pour le chaos. Se ne garde rien, il n'y a donc rien sur quoi s'appuyer.",provenance:"currents"},"se.lab.narration.blackout2":{figure:"Les compteurs se remettent en place.",mechanism:"Contact rétabli — aucun résidu, aucun retard, aucune rancune. Le coût du blackout est égal à sa durée et rien de plus. Les fonctions qui gardent des registres récupèrent lentement ; celle qui ne garde rien est aussi celle qui se réinitialise instantanément.",provenance:"currents"},"se.lab.narration.flicker":{figure:"Notez le double scintillement à l'extérieur de la lentille : même événement, même taille, resté invisible. C'est le même monde sans Se pointé vers lui.",mechanism:"Un élément dans le champ a bougé pendant trois cents millisecondes, et le verrou s'est refermé avant la pensée — un nom pour ce qui a bougé arrive en second.",provenance:"currents"},"se.lab.narration.flicker2":{figure:"Le vacillement a déjà quitté la chambre, et l'œil est de nouveau à la chasse.",mechanism:"Capturé, marqué, relâché — rien n'est stocké. Ce que Se achète n'est pas un souvenir du changement ; c'est la poignée de millisecondes entre le mouvement du monde et la connaissance du corps.",provenance:"currents"},"se.lab.narration.flickerMiss":{figure:"Le vacillement a duré trois cents millisecondes et s'est interrompu avant l'arrivée du verrou.",mechanism:"Manqué. L'événement était réel et la perception honnête — mais depuis cette profondeur de la pile, le signal atteint l'œil après que le moment est passé. Trop tard pour compter est un coût de position, pas un défaut de caractère. Remontez Se le long du rail dans la Zone B et réessayez.",provenance:"currents"},"se.lab.narration.hoverCoarse":"Votre toucher est désormais l'objet le plus vif dans le champ, et l'œil le traite en conséquence : suivi sans latence, traînées surgissant à chaque mouvement rapide. Vous vivez le préréglage dominante — déposez ce glyphe en inférieure dans la Zone B et ce même toucher devient quelque chose que le regard suit à la traîne, saisit et perd.","se.lab.narration.hoverFine":"Le curseur est désormais l'objet le plus vif dans le champ, et l'œil le traite en conséquence : un suivi sans latence, des traînées surgissant à chaque mouvement rapide. Vous vivez le préréglage dominante — déposez ce glyphe en inférieure dans la Zone B et le même curseur devient quelque chose que le regard suit en retard, saisit, puis perd.","se.lab.narration.intro":"Le champ est en direct : dérives, mouvements, l'éclair occasionnel — et l'œil qui traque à travers lui, verrouillant tout ce qui bouge. Ajustez l'intensité du champ et regardez le stress et le plaisir échanger leurs places, ou générez un événement et regardez le réticule répondre.","se.lab.narration.introHintCoarse":"Appuyez et faites glisser dans la chambre pour devenir vous-même la cible.","se.lab.narration.introHintFine":"Survolez la chambre pour devenir vous-même la cible.","se.lab.narration.slider":{figure:"Faites glisser le champ de la pièce vide vers le carnaval de rue et regardez les compteurs échanger leurs places — le rendu s'affine à mesure que le flux s'épaissit.",mechanism:"Plus de monde produit plus de clarté : Se n'est pas submergé par l'intensité, il se concentre. L'urgence, pour cette fonction, est l'autre extrémité du curseur.",provenance:"currents"},"se.lab.narration.window":{figure:"Observez la série de réponses face à l'écart qui se réduit.",mechanism:"Une ouverture — et elle se ferme déjà. La perception ici n'est pas un rapport ; c'est une condition de lancement, et la réponse part immédiatement.",provenance:"currents"},"se.lab.narration.windowHit":{figure:"Une traînée, un intervalle, la lumière du jour des deux côtés.",mechanism:"Filé, avec de la marge. Le présent offrait une brèche avec une échéance, et la voir et la saisir étaient un seul mouvement. Aucune délibération n'apparaît nulle part dans la boucle — ce qui n'est pas de l'imprudence ; à cette position, c'est de la précision.",provenance:"currents"},"se.lab.narration.windowMiss":{figure:"La traînée rencontre le bord fermé.",mechanism:"Fermer. La réponse a été déclenchée exactement comme prévu — et a buté sur un mur, car depuis ce siège, le signal passe des centaines de millisecondes en transit avant même que le lancement ne commence. Sélectionnez un emplacement plus élevé dans la Zone B et générez une autre fenêtre : position est la différence entre une ouverture et une histoire à son sujet.",provenance:"currents"},"se.lab.state.blackout":"Noir sensoriel","se.lab.state.equilibrium":"Champ Ouvert","se.lab.state.flow":"Contact complet","se.lab.state.hunger":"Faim du stimulus","se.lab.state.late":"Hors de position","se.lab.telemetry.clarity":"Clarté du champ","se.lab.telemetry.cogState":"État cognitif","se.lab.telemetry.crossHead":"écoute croisée · les mêmes événements, arrivant à Si","se.lab.telemetry.lock":"Temps de verrouillage","se.lab.telemetry.sibPleasure":"Plaisir Si","se.lab.telemetry.sibStress":"Stress Si","se.lab.telemetry.visitSi":"visiter Si","se.meta.title":"Se — Sensation Extravertie · CURRENTS","se.slot.auxiliary":{example:"Un ISTP jette un coup d'œil au moteur et sait lequel des quatre sons n'a pas sa place.",figure:"L'iris s'ouvre complètement au signal et reste à demi-clos entre.",mechanism:"Dans le siège secondaire, la scène est lue clairement puis transmise vers l'intérieur — à une structure ou une valeur — avant que quoi que ce soit ne soit fait à son sujet. Moins d'appétit qu'en premier siège, plus de sélection : attention totale pour ce que l'artisanat ou le sentiment importe actuellement, mise en attente polie pour le reste.",provenance:"myers"},"se.slot.critical":{example:"Un ESFJ revit une semaine durant le plateau tombé, image par image, sans qu'on lui ait jamais dit comment en porter deux.",figure:"Un réticule de relecture entourant la trame manquée.",mechanism:"Dans le siège tertiaire, l'œil se tourne vers l'intérieur comme un sergent avec un timing parfait et sans chaleur : vous ne l'avez pas vu, vous étiez trop lent, vous étiez ridicule. Précis sur le moment manqué, inutile sur ce qu'en faire, et visant surtout le soi.",provenance:"beebe"},"se.slot.demon":{example:"À la fin d'un mois terrible, un ENFP court jusqu'à ce que ses jambes lâchent, sur une route qu'il n'a jamais vue.",figure:"L'iris restait bloqué ouvert, déversant tout intentionnellement.",mechanism:"Le huitième siège est le plus rare et le plus brut. Lorsqu'il y a éruption, la sensation cesse d'être une perception et devient quelque chose d'appliqué au soi — l'entraînement punitif, la nuit de blackout, la main à travers le mur. C'est le siège le moins pratiqué dans la pile, et à ce stade, il ne voit plus rien.",provenance:"beebe"},"se.slot.dominant":{example:"En milieu de partie, un ESTP est déjà en mouvement quand la voie s'ouvre ; lorsqu'on lui demande comment il le savait, il répond qu'il l'a vu.",figure:"CURRENTS dessine cela comme une iris grande ouverte — le champ est net et saturé à l'intérieur de l'anneau, flou à l'extérieur.",mechanism:"Dans le premier siège, le monde arrive à résolution complète et sans délai : ce qui a bougé, ce qui a changé, où est l'ouverture — évident, continuellement, sans coût. L'attention va là où se trouve l'action sans être envoyée, et le corps répond souvent avant qu'un plan n'existe. Le prix est la rétention : presque rien n'est conservé.",provenance:"myers"},"se.slot.inferior":{example:"Un INFJ qui oublie de manger toute la semaine commande tout ce qu'il y a sur le menu à minuit, deux fois.",figure:"Un trou d'épingle qui s'ouvre brusquement à pleine ouverture sans prévenir.",mechanism:"Dans le siège tertiaire, le présent est surtout statique entre les intuitions : le détail physique arrive tard, partiel et légèrement peu fiable — où sont les clés, ce qui vient d'être dit, l'état du corps. Sous un stress réel, les sens s'ouvrent tous d'un coup — l'emprise de Quenk — avec une consommation excessive, de l'imprudence et un appétit soudain pour l'intensité qui ne leur ressemble pas.",provenance:"quenk"},"se.slot.opposing":{example:"Un ISTJ qui « ne remarque pas la décoration » énumère les quatre changements de la pièce pour gagner un point sur le vieux canapé.",figure:"Sous la ligne de flottaison, l'iris s'ouvre brusquement une fois, de manière significative.",mechanism:"Le cinquième siège ouvre l'ombre — les quatre positions qu'une personne utilise rarement, et surtout sans s'en apercevoir. Ici, le contact s'éveille comme contradiction : quand le registre dit une chose et que la pièce en montre clairement une autre, un regard brut, inhabituellement vif, il est juste là — maintenu exactement assez longtemps pour défendre l'archive, puis abandonné.",provenance:"beebe"},"se.slot.tertiary":{example:"Un ENTJ est pleinement dans son corps lors de la sortie du samedi ; le lundi, les sens sont de nouveau tournés vers la synthèse.",figure:"Une iris à demi-taille sur un minuteur.",mechanism:"Dans le siège tertiaire, la présence survient par bouffées, généralement en aval d'un plan : le dîner, la cour, la scène sont véritablement vus — puis la machinerie à longue portée reprend et les sens reviennent au résumé exécutif. Elle s'améliore avec l'âge, principalement comme permission : il s'avère que le monde est autorisé à être apprécié directement.",provenance:"grant"},"se.slot.trickster":{example:"Un INTP cherche pendant vingt minutes les lunettes sur son propre front, puis jure que la tasse n'y était jamais.",figure:"Le réticule se verrouille, avec assurance, sur un espace vide.",mechanism:"Dans le siège sept, le présent joue des tours : des objets disparaissent et réapparaissent réellement, la chose évidente sur la table devient invisible pendant dix minutes — et parfois l'inverse, une certitude totale sur un détail physique qui n'a jamais existé. Aucun des deux états n'annonce lequel est actif.",provenance:"beebe"},"se.zoneA.canvasAria":"Représentation visuelle interactive de Se comme une ouverture d'iris grande ouverte : un champ de particules en direct s'écoule flou à l'extérieur de l'anneau et net, saturé et avec une traînée à l'intérieur, tandis qu'un réticule de regard effectue des saccades vers tout ce qui bouge et le verrouille dans un cadre. Déplacez ou faites glisser le pointeur pour devenir l'objet le plus vif du champ.","se.zoneB.ageNote":"Avec l'âge, les positions inférieures de la pile gagnent en fidélité, en cycle de service et en stabilité de regard.","se.zoneB.heading":"Les huit visages de Se","se.zoneB.lede":"Le canevas dépeint Se comme un œil en contact avec un champ vivant. La position de Se dans la pile d'une personne — l'ordre fixe dans lequel ses huit fonctions apparaissent — décide de la rapidité de ce contact. Cliquez sur une position pour voir le changement, du verrouillage sans délai de la dominante aux observations confiantes du trickster de choses qui n'étaient jamais là, et regardez le taux de capture décliner le long de la pile. Faites glisser le curseur de maturité pour voir les sièges inférieurs se stabiliser avec l'âge.","se.zoneB.railAria":"Positions de la pile pour Se","se.zoneC.heading":"Qu'alimente Se ?","se.zoneC.lede":"Se rassemble ; elle ne juge pas. La perception extravertie est alimentée par le jugement introverti, ses véritables partenaires sont donc Ti et Fi — les juges intérieurs qui indiquent à l'œil ce qui importe. Cliquez sur une alimentatrice et regardez la saillance se réorganiser.","se.zoneC.unstableDefault":"Couplage instable : la perception alimente la perception, sans que rien ne juge l'une ou l'autre.","se.zoneD.canvasAria":"Le laboratoire de contact Se : un champ de stimulus en direct avec un curseur d'intensité, un regard saccadé qui verrouille les scintillements, une fenêtre qui se ferme à travers laquelle il émet une réponse, et un blackout qui le prive.","se.zoneD.heading":"Le Laboratoire de Contact","se.zoneD.kicker":"Zone D · le labo de contact","se.zoneD.lede":"Se est un instrument de contact : sa qualité se mesure en millisecondes pour verrouiller et en ouvertures utilisées, non en conclusions. Ce laboratoire confronte l'œil à un champ vivant que vous contrôlez. Faites varier l'intensité d'une pièce vide à un carnaval de rue, générez des événements et notez quel bout du curseur est interprété comme l'urgence.","se.zoneE.lede":"Des motifs sauvages — comment Se se manifeste dans la vie quotidienne."};export{e as _meta,n as default};
